+function resolveJiraBaseUrl(config) {
+    var raw = _sectionOf(config, 'tracker').baseUrl || _sectionOf(config, 'jira').baseUrl || _readJiraBasePathEnv();
+    return String(raw || '').trim().replace(/\/+$/, '');
